head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > P > src]<br/>Image 컴포넌트에 표시할 이미지를 URL 로 설정합니다.",
    "validation" : [
        "ref 속성 설정 시 src 속성은 무시됩니다.",
        "FilePath 값 설정 시, Image 컴포넌트에 표시할 이미지의 URL 을 설정합니다.",
        "FilePath 값 설정 시, 상대경로, 절대경로, 프로토콜 포함 경로를 설정할 수 있습니다.",
        "FilePath 값 설정 시, 'data:' 로 시작하는 Data URL 형식을 설정할 수 있습니다.",
        "FilePath 값 설정 시, PNG, JPG, JPEG, GIF, SVG 등 웹브라우저가 지원하는 모든 이미지 파일을 설정할 수 있습니다.",
        "속성값을 설정하지 않으면 현재 XML 페이지의 URL 경로가 설정됩니다.",
        "src 속성값은 기준 경로에 맞게 보정된 뒤 이미지 요청에 사용됩니다.",
        "경로 보정이 적용되므로 src 속성값과 요청되는 주소는 다를 수 있으며, 실제 주소는 getSrc() 메소드로 확인합니다.",
    ]
}



scwin.onpageload = function () {
    // 정적 select1 초기값 설정 (src : 절대경로 PNG / ref : 미설정)
    con_src.setValue("/img/png.png");
    con_ref.setValue("");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (scwin.target1) {
        scwin.target1.remove();
        scwin.target1 = null;
    }

    let cSrc = con_src.getValue();
    let cRef = con_ref.getValue();

    // ref 바인딩 시 이미지가 바로 표시되도록 행 0 을 선택한 상태로 시작한다
    dlt_image.setRowPosition(0);

    let lblSrc = (cSrc === '') ? '미설정' : scwin.shortUrl(cSrc);
    let lblRef = (cRef === '') ? '미설정' : cRef;

    $c.gcm.createLabel('label="[현재] src = ' + lblSrc + ' / ref = ' + lblRef + '\n[절차] con 값 변경 -> Target 재생성 -> src 상태 확인 버튼 클릭\n[참고] ref 바인딩 데이터값 = /img/icon_F.png / 프로토콜 포함 경로는 외부망 미연결 시 표시에 실패할 수 있으며 요청 주소로 확인합니다"', '', 'label1');

    // 조건 설정
    let properties = {
        ref : cRef,
    };

    let cList = $c.gcm.createCList(properties);

    // src 를 con 값으로 가변해야 하므로 공통 함수($c.gcm.createBasicImage 는 src 고정) 대신 직접 생성한다
    let grp_comp = $c.gcm.getTestGroup('');

    let strSrc = (cSrc === '') ? '' : ' src="' + cSrc + '"';

    let strTarget = '<xf:image ' + $c.gcm.strNameSpace + ' ' + cList + strSrc + '></xf:image>';

    scwin.target1 = await $p.dynamicCreate("target1", "image", strTarget, grp_comp);

    // 이미지 로드 성공 / 실패가 확정된 후에 표시 상태를 관측할 수 있으므로 대기한다
    await scwin.waitImage();
}



// 이미지 로드(성공/실패) 확정 대기
scwin.waitImage = function () {
    return new Promise(function (resolve) {
        let img = scwin.target1.render;

        if (img.complete) {
            resolve();
            return;
        }

        img.addEventListener("load", resolve, { once : true });
        img.addEventListener("error", resolve, { once : true });
        setTimeout(resolve, 2000);
    });
}



// 긴 URL(Data URL 등) 축약
scwin.shortUrl = function (url) {
    return (url.length > 60) ? url.substring(0, 60) + " ...(전체 길이 " + url.length + ")" : url;
}



// 이미지 표시 여부 판정 (src 문자열이 아니라 로드 성공 여부로 판정, 크기는 getBox 로 병행 확인)
scwin.isShown = function () {
    let img = scwin.target1.render;
    return img.complete && img.naturalWidth > 0;
}



// 이미지 실측 크기 (원본 / 렌더 박스)
scwin.getBox = function () {
    let img = scwin.target1.render;

    return "원본 " + img.naturalWidth + "x" + img.naturalHeight + ", 렌더 " + img.offsetWidth + "x" + img.offsetHeight;
}



// src 설정값의 유형 (경로 유형 + 이미지 파일 형식 / Data URL / 미설정)
scwin.getSrcType = function (cSrc) {
    if (cSrc === '') return '미설정';
    if (cSrc.indexOf("data:") === 0) return 'Data URL';

    let kind = (cSrc.indexOf("://") > -1) ? '프로토콜 포함 경로' : (cSrc.charAt(0) === '/') ? '절대경로' : '상대경로';
    let idx = cSrc.lastIndexOf(".");

    return (idx < 0) ? kind : kind + " (" + cSrc.substring(idx + 1).toUpperCase() + ")";
}



// validation 1 ~ 8 판정 출력
scwin.btn_getSrcState_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let img = scwin.target1.render;

    let cSrc = con_src.getValue();
    let cRef = con_ref.getValue();

    let strSet = (cSrc === '') ? "미설정" : scwin.shortUrl(cSrc);

    // 실제 요청 주소는 getSrc() 로 확인한다 (@spec : 실제 주소는 getSrc() 메소드로 확인)
    let realSrc = scwin.target1.getSrc();
    let attrSrc = img.getAttribute("src");

    // [1] ref 설정 시 src 무시 (ref 설정 시 src 기준 판정 [2~8] 은 대상이 아니므로 이 줄만 출력)
    if (cRef !== '') {
        let bindValue = dlt_image.getCellData(dlt_image.getRowPosition(), "imgPath");

        bottom.setReturnValue("[1] ref : " + cRef + " / src 설정값 : " + strSet + " / 요청 주소 : " + scwin.shortUrl(realSrc) + " / src 무시 : " + (realSrc.indexOf(bindValue) > -1));
        return;
    }

    // [2~5] 설정한 URL / 유형(경로 유형 + 파일 형식 또는 Data URL) / 표시 상태
    bottom.setReturnValue("[2~5] src 설정값 : " + strSet + " / 유형 : " + scwin.getSrcType(cSrc) + " / 표시 : " + scwin.isShown() + " (" + scwin.getBox() + ")");

    // [6] 미설정 시 현재 XML 페이지의 URL 경로 (미설정일 때만 대상, 경로 보정 대상도 아님)
    if (cSrc === '') {
        bottom.setReturnValue("[6] src 미설정 / 요청 주소 : " + realSrc + " / 페이지 URL 일치 : " + (realSrc === document.location.href));
        return;
    }

    // [7,8] 설정값 -> 보정된 속성값 -> getSrc() 실제 요청 주소 (Data URL 은 경로 보정 대상 아님)
    if (cSrc.indexOf("data:") !== 0) {
        bottom.setReturnValue("[7,8] 설정값 : " + cSrc + " -> 보정 속성값 : " + scwin.shortUrl(attrSrc) + " -> getSrc() : " + scwin.shortUrl(realSrc) + " / 설정값과 동일 : " + (cSrc === realSrc));
    }
};
